insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MR', 'default', 'Plan comptable national — plan comptable général (classes 1 à 8)', '{}'::jsonb, true, 'companies', array['MR-PCN-BILAN', 'MR-PCN-RESULTATS']::text[], null, 'Ordonnance n° 82-180 du 24 décembre 1982 portant institution d''un Plan comptable national, art. 1er — le Plan comptable général annexé est le plan de comptes ; les comptes principaux à deux chiffres des classes 1 à 8 sont obligatoires, les comptes divisionnaires (trois chiffres et plus) sont donnés à titre indicatif ; le Code général des impôts, art. L.16, exige une comptabilité conforme au référentiel comptable mauritanien. Le pack reprend les comptes à deux chiffres et une sélection de comptes divisionnaires, aux numéros du plan, suffisante pour tenir des livres de sociétés commerciales ; la loi n° 99-009 du 20 janvier 1999 portant révision du plan comptable n''a pas pu être lue (voir le README). Ajouts propres au pack, absents de la liste du plan : 4356 (crédit de TVA à reporter ou à rembourser, pour que le compte de règlement 4355 reste distinct des comptes où la taxe se poste), 4361 (TVA due à la douane), 5501 et 5502 (banque en devises, à l''étranger), 4000 et 4100 en comptes de tiers lettrables, 6489 (arrondis).', 'pcn')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

