insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('MR', 'MR-P-16', 'Achats taux normal 16 % — déductible', '{}'::jsonb, 'Achat de biens ou de services dont la taxe est déductible', 'percent', 16, 'purchase', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 231 et 232 — la taxe qui a grevé les éléments du prix d''une opération imposable est déductible : matières premières, biens destinés à la revente, services entrant dans le prix de revient, immobilisations et frais généraux ; art. 249-3 — la déduction est justifiée par un état signé et cacheté, donnant le NIF du fournisseur, la référence et le montant de la facture ; sans cet état, les déductions sont réintégrées. La taxe déductible est portée au compte 4350 (État, taxes récupérables).', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2023', null, null, null, null),
  ('MR', 'MR-P-16-ND', 'Achats taux normal 16 % — taxe non déductible', '{}'::jsonb, 'Achat dont la taxe n''est pas déductible : réceptions, véhicules de tourisme, paiement en espèces supérieur à 200 000 MRU, facture sans NIF', 'percent', 16, 'purchase', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 233 — n''est pas déductible la taxe qui a grevé les frais de réception et de restaurant (1°), les biens cédés gratuitement (2°), les acquisitions entre professionnels réglées en espèces pour plus de 200 000 MRU (3°), les acquisitions dont la facture ne porte pas le NIF du fournisseur (4°), les véhicules de tourisme (5°), les immeubles autres que les locaux professionnels (6°), les meubles (7°). La taxe suit la charge au compte 661, sans case de déclaration.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2023', null, null, null, null),
  ('MR', 'MR-P-EX', 'Achats exonérés', '{}'::jsonb, 'Achat d''une opération exonérée ou hors champ : aucune taxe', 'percent', 0, 'purchase', 'exempt', date '2022-01-01', null, 'Code général des impôts, art. 215 et 214 — une opération exonérée ou hors du champ d''application ne porte pas de taxe, l''achat n''ouvre aucune déduction ; la déclaration n''a pas de ligne pour un achat exonéré.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2023', null, null, null, null),
  ('MR', 'MR-P-IMP', 'Importation de biens — taxe payée à la douane', '{}'::jsonb, 'Taxe sur la valeur ajoutée payée à l''importation, avant l''enlèvement de la marchandise', 'percent', 16, 'purchase', 'import', date '2022-01-01', null, 'Code général des impôts, art. 222-1° — la base des importations est la valeur en douane, taxes de toute nature perçues au cordon douanier comprises ; art. 227-1 et 228-1 — fait générateur au franchissement du cordon douanier, exigibilité à la mise à la consommation ; art. 254 — les importateurs déclarent et versent la taxe avant l''enlèvement ; art. 232 — la taxe payée à l''importation est déductible. La taxe est déduite au compte 4350 et due à la douane au compte 4361 jusqu''à son règlement.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2023', null, null, null, null),
  ('MR', 'MR-S-16', 'Ventes taux normal 16 %', '{}'::jsonb, 'Livraisons de biens et prestations de services imposables au taux normal', 'percent', 16, 'sale', 'domestic', date '2022-01-01', null, 'Code général des impôts, art. 230-1 (LFI 2022) — taux normal de 16 % ; art. 210 et 211 — opérations imposables, assujettis dont le chiffre d''affaires annuel hors taxes atteint 3 000 000 MRU ; art. 222 à 226 — base d''imposition, arrondie à la dizaine d''ouguiya inférieure (art. 226), arrondi que le pack ne modélise pas ; art. 253 — la taxe est à la charge du consommateur. La taxe collectée est portée au compte 4357 (État, taxes collectées) du plan comptable.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2023', null, null, null, null),
  ('MR', 'MR-S-EX', 'Ventes exonérées', '{}'::jsonb, 'Opérations que l''article 215 exonère : actes médicaux, enseignement, produits alimentaires de base, transport public, etc.', 'percent', 0, 'sale', 'exempt', date '2022-01-01', null, 'Code général des impôts, art. 215 — liste des opérations exonérées de la taxe sur la valeur ajoutée (actes médicaux, enseignement agréé, eau et électricité jusqu''à 8 m³ et 150 kWh par mois, lait, riz, farine, pain, légumes, viandes et poissons frais, etc.) ; art. 233-8 — la taxe qui grève les achats d''une exportation de produits non taxables à l''intérieur n''est pas déductible ; la facture porte la mention « Exonéré » (art. L.21). Les exonérations sont à faire valider par un comptable local : le pack ne code pas la liste article par article.', 'E', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2023', null, null, null, null),
  ('MR', 'MR-S-Z-EXP', 'Ventes à l''exportation (taux zéro)', '{}'::jsonb, 'Exportations de biens et de services réalisées par un assujetti', 'percent', 0, 'sale', 'export', date '2022-01-01', null, 'Code général des impôts, art. 230-2 — taux zéro (0 %) pour les exportations de biens et services réalisées par un assujetti ; art. 231-2 — les exportations de produits taxables à l''intérieur ouvrent droit à déduction ; art. 245-1-a — le crédit de taxe des exportateurs est remboursable (art. 246 : demande écrite, crédit d''au moins 100 000 MRU, trois dernières déclarations créditrices).', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi2023', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

