values
  ('MR', 'MR-TVA', 'Déclaration mensuelle de la taxe sur la valeur ajoutée', array['month']::declaration_period[], 'month'::declaration_period, date '2022-01-01', null, 'Code général des impôts, art. 249-1 — tout redevable dépose chaque mois, à l''appui de son versement entre les mains du receveur des impôts, une déclaration conforme au modèle prescrit ; art. 249-2 — elle indique le montant total des opérations, le détail des opérations taxables, la taxe déductible et le décompte de la taxe exigible ; art. 249-3 — elle est accompagnée d''un état des déductions ; art. 250-1 — une déclaration « Néant » est déposée pour un mois sans opération ; art. 244 — l''excédent de déduction est un crédit imputable sur les déclarations suivantes. Le modèle prescrit n''a pas pu être lu : les cases ci-dessous sont celles du pack, regroupées sous les chiffres que le Code nomme, et le manque est écrit dans le README.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Code général des impôts, art. 250-1 — la déclaration d''un mois donné est déposée au plus tard le 15 du mois suivant ; art. 254 — le paiement accompagne la déclaration. Le Code ne dit pas ce qu''il advient d''un 15 férié.', 'cgi2023', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
