  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Code général des impôts, art. 227 et 228 — le fait générateur des ventes est la livraison et celui des prestations de services l''accomplissement du service, mais la taxe sur les prestations de services est exigible à l''encaissement du prix ou des acomptes (art. 228-5), et sur les marchés publics à chaque paiement du Trésor (art. 228-7). Le pack déclare `delivery_date`, qui est le principe pour les biens ; l''exigibilité des services à l''encaissement n''est pas modélisée (le code `MR-S-16` ne porte pas `cash_basis`) et le manque est écrit dans le README.',
  tax_point_source_key          = 'cgi2023',
